import type { TopicalExam } from './types'

function q(id: number, question: string, options: string[], correctAnswer: number, explanation: string) {
  return { id, question, options, correctAnswer, explanation }
}

export const TOPICAL_MICRO: TopicalExam = {
  label: 'AP Microeconomics',
  slug: 'ap-microeconomics',
  units: [
    {
      unitNumber: 1,
      title: 'Basic Economic Concepts',
      easy: [
        q(1, 'The law of demand states that, ceteris paribus:', ['As the price of a good increases, the quantity demanded increases.', 'As the price of a good increases, the quantity demanded decreases.', 'As income increases, demand for all goods increases.', 'As supply increases, demand increases.'], 1, 'The law of demand states that there is an inverse relationship between price and quantity demanded, holding all other factors constant (ceteris paribus). As price rises, consumers buy less; as price falls, consumers buy more.'),
        q(2, 'A movement along the demand curve is caused by:', ['A change in consumer income', 'A change in the price of the good itself', 'A change in consumer preferences', 'A change in the number of buyers'], 1, 'A movement along the demand curve (change in quantity demanded) is caused only by a change in the good\'s own price. All other factors (income, preferences, prices of related goods, expectations, number of buyers) cause a shift of the entire demand curve.'),
        q(3, 'Which of the following would shift the supply curve for wheat to the right?', ['An increase in the price of wheat', 'An increase in the cost of fertilizer', 'Favorable weather conditions improving crop yields', 'A decrease in government subsidies for farming'], 2, 'Favorable weather increases wheat productivity, allowing farmers to produce more at every price level. This shifts the supply curve to the right. A change in the price of wheat would cause a movement along the curve, not a shift.'),
        q(4, 'Market equilibrium occurs when:', ['Government sets the price at an optimal level', 'Quantity demanded equals quantity supplied at a given price', 'All consumers can afford the good', 'Producers maximize their revenue'], 1, 'Market equilibrium is reached at the price where the quantity consumers want to buy equals the quantity producers want to sell. At this price, there is no surplus or shortage, and the market clears.'),
        q(5, 'If the price of a good is set above the equilibrium price, the result is:', ['A shortage', 'A surplus, because quantity supplied exceeds quantity demanded', 'Market equilibrium', 'Increased demand'], 1, 'When price is above equilibrium, the quantity supplied exceeds the quantity demanded (producers want to sell more than consumers want to buy), creating a surplus. This surplus puts downward pressure on the price toward equilibrium.'),
      ],
      medium: [
        q(6, 'Coffee and tea are substitute goods. If the price of coffee increases, what happens in the market for tea?', ['Demand for tea decreases, lowering the price of tea.', 'Demand for tea increases (shifts right), raising the equilibrium price and quantity of tea.', 'Supply of tea increases, lowering the price of tea.', 'The market for tea is unaffected.'], 1, 'When the price of a substitute (coffee) rises, consumers switch to the alternative (tea), increasing demand for tea (rightward shift of the tea demand curve). This leads to a higher equilibrium price and higher equilibrium quantity of tea.'),
        q(7, 'A price ceiling set below the equilibrium price will result in:', ['A surplus of the good', 'A shortage, because quantity demanded exceeds quantity supplied at the ceiling price', 'No effect on the market', 'Increased production to meet demand'], 1, 'A binding price ceiling (below equilibrium) keeps the price artificially low. At the lower price, consumers want to buy more (higher Qd) and producers want to sell less (lower Qs). The result is a shortage (Qd > Qs) and the quantity actually traded equals Qs.'),
        q(8, 'Elasticity of demand measures:', ['The slope of the demand curve', 'The responsiveness of quantity demanded to a change in price', 'The total amount consumers spend on a good', 'The change in supply when price changes'], 1, 'Price elasticity of demand measures the percentage change in quantity demanded divided by the percentage change in price. It captures how responsive (sensitive) consumers are to price changes, independent of units of measurement.'),
        q(9, 'If a 10% increase in price leads to a 5% decrease in quantity demanded, the price elasticity of demand is:', ['2.0 (elastic)', '0.5 (inelastic)', '1.0 (unit elastic)', '5.0 (perfectly elastic)'], 1, 'Price elasticity of demand = % change in Qd / % change in price = 5% / 10% = 0.5. Since the absolute value is less than 1, demand is inelastic—quantity demanded is relatively unresponsive to price changes.'),
        q(10, 'Consumer surplus is the difference between:', ['The market price and the cost of production', 'What consumers are willing to pay for a good and what they actually pay', 'Total revenue and total cost for producers', 'The equilibrium price and the minimum price'], 1, 'Consumer surplus is the difference between consumers\' maximum willingness to pay (represented by the demand curve) and the actual market price. Graphically, it is the area below the demand curve and above the price, representing the net benefit consumers receive from market transactions.'),
      ],
      hard: [
        q(11, 'A government imposes a per-unit tax on producers in a competitive market. If demand is perfectly inelastic, what portion of the tax burden falls on consumers?', ['None—producers bear the entire tax burden.', 'Consumers bear the entire tax burden because they will pay any price for the good.', 'The burden is split equally between consumers and producers.', 'The portion depends on the elasticity of supply.'], 1, 'With perfectly inelastic demand (vertical demand curve), consumers have no ability to reduce their purchases when price rises. The entire tax burden is shifted to consumers through higher prices because quantity demanded doesn\'t change regardless of price. The more inelastic the demand relative to supply, the greater the share of tax burden on consumers.'),
        q(12, 'In a market with a positive externality (such as education), the socially optimal quantity is:', ['Less than the market equilibrium quantity', 'Greater than the market equilibrium quantity because the market underproduces goods with positive externalities', 'Equal to the market equilibrium quantity', 'Zero, because the market fails completely'], 1, 'Positive externalities create benefits for third parties not captured in market prices. The social benefit exceeds the private benefit, so the socially optimal quantity is higher than what the market produces. The market underproduces goods with positive externalities because producers and consumers don\'t account for the external benefits.'),
        q(13, 'When both supply and demand increase simultaneously, the effect on equilibrium quantity is clear, but the effect on equilibrium price is ambiguous. Why?', ['Both shifts push price in the same direction.', 'The demand increase pushes price up while the supply increase pushes price down; the net effect depends on the relative magnitudes of the shifts.', 'Price always increases when both curves shift right.', 'Price changes are never ambiguous in supply and demand analysis.'], 1, 'An increase in demand (rightward shift) tends to raise equilibrium price, while an increase in supply (rightward shift) tends to lower it. Both shifts increase equilibrium quantity (reinforcing effects), but they have opposing effects on price. The net price change depends on which shift is larger—if demand increases more, price rises; if supply increases more, price falls.'),
        q(14, 'A price floor set above equilibrium in the labor market (minimum wage above market wage) would theoretically result in:', ['A shortage of labor', 'A surplus of labor (unemployment), as quantity of labor supplied exceeds quantity demanded at the higher wage', 'No effect on employment', 'Increased demand for labor'], 1, 'A minimum wage above the equilibrium wage increases the quantity of labor supplied (more workers want to work at higher wages) and decreases the quantity demanded (employers hire fewer workers at higher cost). The result is a surplus of labor—more workers seeking jobs than employers willing to hire—which manifests as unemployment.'),
        q(15, 'Deadweight loss from a per-unit tax represents:', ['Revenue transferred from consumers to the government.', 'The net loss of total surplus (consumer + producer surplus) that is not captured by anyone—transactions that would have occurred without the tax but no longer do.', 'The total tax revenue collected by the government.', 'The increase in producer costs due to the tax.'], 1, 'Deadweight loss is the reduction in total surplus that results from the tax reducing the quantity traded below the efficient (equilibrium) level. It represents the value of mutually beneficial transactions that no longer occur—surplus that is lost to society and not captured by consumers, producers, or the government.'),
      ],
    },
    {
      unitNumber: 2,
      title: 'Production, Cost, and the Perfect Competition Model',
      easy: [
        q(16, 'The law of diminishing marginal returns states that:', ['Total output always decreases as more inputs are added.', 'As additional units of a variable input are added to fixed inputs, the marginal product of the variable input eventually decreases.', 'Average costs always increase with output.', 'Firms should always minimize the number of workers.'], 1, 'The law of diminishing marginal returns states that when a variable input (like labor) is added to a fixed input (like capital), the additional output from each successive unit of the variable input will eventually decline. This occurs because the fixed input becomes increasingly strained.'),
        q(17, 'Fixed costs in the short run are costs that:', ['Change with the level of output', 'Do not change regardless of the level of output', 'Only exist in the long run', 'Equal zero when output is zero'], 1, 'Fixed costs remain constant regardless of how much or how little a firm produces in the short run. Examples include rent, insurance premiums, and loan payments. These costs exist even if output is zero.'),
        q(18, 'In perfect competition, a firm is a price taker because:', ['It sets the market price for its product.', 'It produces a unique product that commands a premium price.', 'It is so small relative to the market that it cannot influence the market price.', 'Government regulations fix the price.'], 2, 'In perfect competition, each firm produces a tiny fraction of total market output and sells an identical (homogeneous) product. No individual firm can influence the market price; it must accept (take) whatever price the market determines.'),
        q(19, 'Marginal cost (MC) is defined as:', ['Total cost divided by quantity of output', 'The change in total cost from producing one additional unit of output', 'Fixed cost plus variable cost', 'Average cost at the profit-maximizing output level'], 1, 'Marginal cost is the additional cost incurred by producing one more unit of output. It is calculated as the change in total cost divided by the change in quantity (MC = ΔTC/ΔQ). It reflects the cost of expanding production by one unit.'),
        q(20, 'A perfectly competitive firm maximizes profit by producing where:', ['Total revenue is maximized', 'Marginal revenue equals marginal cost (MR = MC)', 'Average total cost is minimized', 'Price exceeds average variable cost by the greatest amount'], 1, 'A profit-maximizing firm produces at the output level where marginal revenue equals marginal cost (MR = MC). Below this output, MR > MC (additional units add more to revenue than cost), and above it, MC > MR (additional units cost more than they earn).'),
      ],
      medium: [
        q(21, 'A firm in perfect competition is currently producing at a level where price is $10, ATC is $8, and AVC is $6. This firm is:', ['Earning economic profit of $2 per unit and should continue producing', 'Breaking even', 'Earning economic losses and should shut down immediately', 'Unable to determine profitability from this information'], 0, 'Since Price ($10) > ATC ($8), the firm earns economic profit of $2 per unit (P - ATC = $10 - $8 = $2). The firm should continue producing because it more than covers all costs, including the opportunity cost of the owner\'s resources (included in ATC as implicit costs).'),
        q(22, 'In the short run, a perfectly competitive firm should shut down rather than continue producing when:', ['Price is below average total cost', 'Price is below average variable cost, because continuing to produce would lose more than just fixed costs', 'Price equals marginal cost', 'Marginal cost is rising'], 1, 'A firm should shut down when P < AVC. If the firm produces, it loses more than its fixed costs because revenue doesn\'t even cover variable costs. By shutting down, losses are limited to fixed costs. If P ≥ AVC but P < ATC, the firm should continue in the short run because revenue covers variable costs and contributes toward fixed costs.'),
        q(23, 'The short-run supply curve for a perfectly competitive firm is:', ['Its entire marginal cost curve', 'The portion of its marginal cost curve above the average variable cost curve', 'Its average total cost curve', 'Its average variable cost curve'], 1, 'The firm\'s short-run supply curve is the portion of its MC curve above AVC. Below AVC, the firm shuts down (quantity supplied = 0). At prices above AVC, the firm produces where P = MC, so the MC curve above AVC shows how much the firm supplies at each price.'),
        q(24, 'Economies of scale occur when:', ['Average total cost increases as output increases', 'Average total cost decreases as output increases due to specialization, bulk purchasing, or spreading fixed costs', 'Marginal cost equals average total cost', 'The firm produces at minimum efficient scale'], 1, 'Economies of scale exist when a firm\'s average total cost falls as output increases. Sources include labor specialization, bulk purchasing discounts, spreading fixed costs over more units, and more efficient use of technology. They explain why larger firms can sometimes produce at lower per-unit costs.'),
        q(25, 'In long-run equilibrium in a perfectly competitive market, firms earn:', ['Positive economic profit', 'Zero economic profit, with price equal to minimum average total cost', 'Negative economic profit', 'Profit determined by government regulation'], 1, 'In long-run equilibrium, free entry and exit drive economic profit to zero. If firms earn positive economic profit, new firms enter (increasing supply, lowering price). If firms earn losses, some exit (decreasing supply, raising price). Equilibrium occurs where P = MR = MC = minimum ATC, and firms earn zero economic profit (but still earn normal/accounting profit).'),
      ],
      hard: [
        q(26, 'A perfectly competitive firm observes that its marginal cost curve intersects its average total cost curve at an output of 100 units and a cost of $15. What is the significance of this intersection?', ['The firm should produce 100 units regardless of the price.', 'This is the minimum point of the ATC curve (minimum efficient scale); if the market price is $15, the firm earns zero economic profit, and this is the long-run equilibrium price.', 'This is the shutdown point for the firm.', 'The firm should produce more than 100 units to maximize profit.'], 1, 'The MC curve intersects ATC at ATC\'s minimum point. This occurs because when MC < ATC, average cost is falling; when MC > ATC, average cost is rising. The intersection represents minimum ATC. In long-run competitive equilibrium, price equals minimum ATC, so if the market price is $15, the firm earns zero economic profit.'),
        q(27, 'In a perfectly competitive industry, firms are currently earning economic profits. Describe the long-run adjustment process.', ['Profits persist indefinitely because no new firms can enter.', 'New firms enter the industry, increasing market supply, which drives down the market price until economic profit is eliminated and P = minimum ATC.', 'Existing firms increase prices to maintain profits.', 'The government intervenes to cap profits.'], 1, 'The absence of barriers to entry means positive economic profits attract new firms. As firms enter, industry supply shifts rightward, reducing the market price. Each firm\'s individual demand curve shifts down. Entry continues until price falls to minimum ATC and economic profit reaches zero—the long-run competitive equilibrium.'),
        q(28, 'A firm\'s production function shows that the 5th worker adds 20 units of output, the 6th worker adds 15 units, and the 7th worker adds 10 units. If each worker is paid $150 per day, the marginal cost of the output produced by the 7th worker is:', ['$7.50 per unit', '$10.00 per unit', '$15.00 per unit', '$150.00 per unit'], 2, 'Marginal cost = Change in total cost / Change in output = Wage / Marginal product of labor = $150 / 10 units = $15 per unit. As diminishing marginal returns reduce the marginal product of labor, the marginal cost of each additional unit of output increases.'),
        q(29, 'In a constant-cost perfectly competitive industry, a permanent increase in demand leads to which long-run outcome?', ['Higher price and more firms', 'The same price as before the demand increase, but a larger number of firms producing the original per-firm quantity at minimum ATC', 'Lower price due to economies of scale', 'Permanently higher economic profits for existing firms'], 1, 'In a constant-cost industry, input prices don\'t change as the industry expands. After demand increases, short-run profits attract entry. New firms enter until economic profit returns to zero. Since input costs haven\'t changed, minimum ATC remains the same, so the long-run price returns to its original level but with more firms in the industry.'),
        q(30, 'A perfectly competitive firm\'s total revenue is $5,000, total fixed cost is $2,000, total variable cost is $4,000, and marginal revenue equals marginal cost at current output. Should this firm continue to operate in the short run?', ['No, because total cost exceeds total revenue.', 'Yes, because total revenue ($5,000) exceeds total variable cost ($4,000), so the firm covers all variable costs and contributes $1,000 toward fixed costs; shutting down would result in losing the entire $2,000 in fixed costs.', 'No, because the firm cannot cover its fixed costs.', 'Yes, because the firm is earning positive economic profit.'], 1, 'The firm should continue operating: TR ($5,000) > TVC ($4,000), so the firm covers variable costs and contributes $1,000 toward fixed costs. Total loss while operating = TC - TR = $6,000 - $5,000 = $1,000. If it shuts down, loss = TFC = $2,000. Operating reduces losses by $1,000 compared to shutting down.'),
      ],
    },
    {
      unitNumber: 3,
      title: 'Imperfect Competition',
      easy: [
        q(31, 'A monopoly differs from perfect competition primarily because a monopoly:', ['Has many small firms', 'Is the sole seller of a product with no close substitutes', 'Produces homogeneous products', 'Faces a perfectly elastic demand curve'], 1, 'A monopoly is a market structure with a single seller producing a good or service with no close substitutes. Unlike perfectly competitive firms, a monopolist is a price maker and faces the entire downward-sloping market demand curve.'),
        q(32, 'A monopolist faces a downward-sloping demand curve. This means that to sell additional units, the monopolist must:', ['Keep the price constant', 'Lower the price on all units sold', 'Raise the price', 'Produce identical goods as competitors'], 1, 'Because the monopolist is the only seller, it faces the entire market demand curve, which slopes downward. To sell more units, it must reduce the price—and this lower price applies to all units sold, not just the additional one.'),
        q(33, 'Monopolistic competition is characterized by:', ['A single firm in the market', 'Many firms selling differentiated products with free entry and exit', 'A few large firms dominating the market', 'Firms producing identical products'], 1, 'Monopolistic competition features many firms selling similar but differentiated products (brand names, quality differences, style). Entry and exit are free, similar to perfect competition, but product differentiation gives each firm some market power.'),
        q(34, 'An oligopoly is a market structure with:', ['A single dominant firm', 'Many small firms with no market power', 'A few large firms whose decisions are interdependent', 'Perfect information and homogeneous products'], 2, 'An oligopoly has a few large firms that dominate the market. The key characteristic is interdependence—each firm\'s pricing and output decisions affect and are affected by the decisions of rival firms, leading to strategic behavior.'),
        q(35, 'A natural monopoly exists when:', ['A firm holds a government-granted patent.', 'A single firm can supply the entire market at a lower average total cost than two or more firms due to economies of scale over the relevant range of output.', 'A firm engages in predatory pricing.', 'The government creates a monopoly through regulation.'], 1, 'A natural monopoly occurs when economies of scale are so large relative to market demand that a single firm can produce at lower average cost than multiple firms. Utilities (water, electricity) are classic examples because the high fixed costs of infrastructure make duplication wasteful.'),
      ],
      medium: [
        q(36, 'For a monopolist, marginal revenue is less than price because:', ['The monopolist has increasing marginal costs.', 'To sell an additional unit, the monopolist must lower the price on all units, so the revenue gained from the extra unit is offset by the revenue lost from reducing the price on all previous units.', 'The monopolist faces a perfectly elastic demand curve.', 'The government taxes each additional unit sold.'], 1, 'The monopolist\'s MR < P because of the price effect. Selling one more unit requires lowering the price on ALL units (not just the additional one). MR = the price of the additional unit minus the revenue lost on all previous units from the price reduction. This makes the MR curve lie below the demand curve.'),
        q(37, 'Compared to a perfectly competitive market, a profit-maximizing monopolist produces:', ['A higher quantity at a lower price', 'A lower quantity at a higher price, creating deadweight loss', 'The same quantity at the same price', 'A higher quantity at a higher price'], 1, 'A monopolist restricts output below the competitive level (where MR = MC rather than P = MC) and charges a higher price. This creates allocative inefficiency: the monopoly price exceeds marginal cost, and some mutually beneficial transactions don\'t occur, resulting in deadweight loss.'),
        q(38, 'In monopolistic competition, long-run equilibrium differs from perfect competition because:', ['Firms earn positive economic profit in the long run.', 'Firms produce at an output where P > MC (allocative inefficiency) and above minimum ATC (productive inefficiency), though economic profit is driven to zero by free entry.', 'There are no barriers to entry.', 'Firms are price takers.'], 1, 'In long-run equilibrium, free entry drives economic profit to zero (like perfect competition). However, because each firm faces a downward-sloping demand curve (due to product differentiation), the tangency with ATC occurs to the left of minimum ATC. This means excess capacity (productive inefficiency) and P > MC (allocative inefficiency).'),
        q(39, 'Game theory is most applicable to which market structure?', ['Perfect competition', 'Monopoly', 'Oligopoly, because firms must consider rivals\' reactions when making strategic decisions', 'Monopolistic competition'], 2, 'Game theory analyzes strategic decision-making where outcomes depend on the actions of multiple decision-makers. This is most relevant to oligopoly, where a few firms are interdependent—each firm\'s optimal strategy depends on how it expects rival firms to react.'),
        q(40, 'Price discrimination occurs when a firm:', ['Charges the same price to all customers', 'Charges different prices to different customers for the same product based on willingness to pay, not cost differences', 'Lowers prices due to decreased demand', 'Raises prices uniformly across all markets'], 1, 'Price discrimination is charging different prices to different consumers (or groups) for the same product when the price differences are not justified by cost differences. It requires market power, the ability to segment customers, and prevention of resale between customer groups.'),
      ],
      hard: [
        q(41, 'A monopolist currently charges $20 per unit and sells 100 units. If it lowers the price to $18 to sell 110 units, what is the marginal revenue of the additional 10 units?', ['$18 per unit', '$180 total', '-$2 per unit', '-$20 total, meaning MR is negative and the firm should not lower the price', 'Not enough information'], 2, 'New TR = $18 × 110 = $1,980. Old TR = $20 × 100 = $2,000. Change in TR = -$20. MR per unit = -$20/10 = -$2. The revenue gained from 10 new units at $18 ($180) is more than offset by the revenue lost from reducing the price by $2 on the original 100 units ($200). MR is negative, meaning the firm is on the inelastic portion of its demand curve.'),
        q(42, 'In a two-firm prisoner\'s dilemma game, both firms would be better off if they cooperated (set high prices). However, the Nash equilibrium is for both to defect (set low prices). Which explains this outcome?', ['Firms always prefer lower prices.', 'Each firm has a dominant strategy to defect (set low prices) because regardless of the other firm\'s choice, defecting yields a better payoff for each individual firm, even though mutual cooperation would make both better off.', 'The government requires firms to compete aggressively.', 'Firms lack the ability to communicate.'], 1, 'In the prisoner\'s dilemma, each firm\'s dominant strategy is to defect (low price): if the rival cooperates, defecting yields a higher payoff; if the rival defects, defecting also yields a higher (or less negative) payoff. Both following their dominant strategy leads to mutual defection—the Nash equilibrium—even though mutual cooperation would maximize joint profits.'),
        q(43, 'A profit-maximizing monopolist operating on the inelastic portion of its demand curve should:', ['Increase output to increase total revenue.', 'Decrease output (raise price) because on the inelastic portion, MR is negative, meaning the firm is producing beyond the profit-maximizing quantity.', 'Maintain current output.', 'Lower price to attract more customers.'], 1, 'On the inelastic portion of demand, MR is negative (additional units reduce total revenue). Since MC is always positive, MR < MC in this region. The firm should reduce output (raise price) until it reaches the elastic portion where MR > 0 and MR = MC. A profit-maximizing monopolist always operates on the elastic portion of its demand curve.'),
        q(44, 'Government regulation of a natural monopoly that sets price equal to marginal cost (P = MC) achieves allocative efficiency but creates a problem because:', ['The firm earns excessive profit.', 'At the output where P = MC, price is below average total cost (due to the declining ATC from economies of scale), forcing the firm to operate at a loss and requiring a government subsidy to remain in business.', 'The firm will overproduce.', 'The firm\'s marginal cost exceeds its average cost at all output levels.'], 1, 'Natural monopolies have declining ATC (economies of scale). Because ATC is declining, MC lies below ATC at every output level. Setting P = MC (the allocatively efficient price) means P < ATC, so the firm cannot cover its costs and earns losses. The firm would exit without a subsidy or alternative solution (average cost pricing, P = ATC, sacrifices some efficiency for firm viability).'),
        q(45, 'A monopolistically competitive firm launches an advertising campaign that increases demand but also increases its average total cost. Under what condition does this advertising improve the firm\'s profitability?', ['Advertising always improves profitability for monopolistically competitive firms.', 'The advertising improves profitability if the increase in total revenue from the rightward shift in demand exceeds the increase in total cost from the advertising expenditure.', 'Advertising never improves profitability because it increases costs.', 'Only if competing firms do not also advertise.'], 1, 'Advertising is profitable when the additional revenue generated (from increased demand and potentially reduced price elasticity) exceeds the additional cost. The demand curve must shift right enough and/or become sufficiently less elastic that the firm can charge a price premium sufficient to more than offset the advertising cost added to ATC.'),
      ],
    },
    {
      unitNumber: 4,
      title: 'Factor Markets',
      easy: [
        q(46, 'The demand for labor is considered a "derived demand" because:', ['Workers derive satisfaction from employment.', 'The demand for labor depends on (is derived from) the demand for the goods and services that labor produces.', 'Labor supply determines labor demand.', 'Wages are derived from government regulations.'], 1, 'Labor demand is derived from product demand—firms hire workers to produce goods that consumers want. If demand for the final product increases, firms need more workers to produce it, increasing labor demand. The value of labor depends on the value of what it produces.'),
        q(47, 'The marginal revenue product (MRP) of labor is calculated as:', ['Total revenue divided by the number of workers', 'Marginal product of labor multiplied by marginal revenue', 'Wage rate multiplied by the number of workers', 'Total cost divided by total output'], 1, 'MRP = MPL × MR (marginal product of labor times marginal revenue from selling output). It represents the additional revenue a firm earns from hiring one more worker. In perfect competition in the output market, MRP = MPL × P (product price).'),
        q(48, 'A profit-maximizing firm in a competitive labor market hires workers until:', ['The wage equals the marginal product of labor', 'The wage equals the marginal revenue product of labor (MRP = W)', 'The marginal cost of labor equals zero', 'All available workers are employed'], 1, 'A firm hires workers until the marginal revenue product (the additional revenue from the last worker) equals the wage (the cost of the last worker). If MRP > W, hiring another worker adds more to revenue than cost, increasing profit. If MRP < W, the worker costs more than they contribute.'),
        q(49, 'In a perfectly competitive labor market, the wage rate is determined by:', ['Individual firms\' decisions', 'The intersection of market labor supply and market labor demand', 'Government minimum wage laws', 'Union negotiations exclusively'], 1, 'In a perfectly competitive labor market, the equilibrium wage is determined by the intersection of market labor supply (all workers in that occupation) and market labor demand (all firms hiring that type of worker). Individual firms are wage takers.'),
        q(50, 'Human capital refers to:', ['Machinery and equipment used in production', 'The skills, knowledge, and experience that make workers more productive', 'Financial capital invested in businesses', 'Raw materials used in manufacturing'], 1, 'Human capital encompasses the education, training, skills, experience, and health that increase workers\' productivity. Investment in human capital (through education, job training) increases workers\' marginal product and typically leads to higher wages.'),
      ],
      medium: [
        q(51, 'If the price of the output a firm produces increases, the firm\'s demand for labor will:', ['Decrease, because higher prices reduce demand for the product', 'Increase, because the marginal revenue product of each worker rises when output price increases', 'Remain unchanged, because labor demand depends only on wages', 'Decrease, because the firm needs fewer workers to earn the same revenue'], 1, 'Since MRP = MPL × P, an increase in output price (P) increases the MRP of each worker. This shifts the firm\'s labor demand curve (which is the MRP curve) to the right, increasing the quantity of labor demanded at every wage rate.'),
        q(52, 'A monopsony in the labor market differs from a competitive labor market because a monopsony:', ['Has many firms competing for workers', 'Is a single buyer of labor that must raise wages to attract additional workers, making its marginal factor cost exceed the wage', 'Pays higher wages than competitive markets', 'Faces a perfectly elastic labor supply curve'], 1, 'A monopsony is a single employer (or dominant employer) in a labor market. Because it faces the entire upward-sloping labor supply curve, it must raise the wage to attract additional workers—and this higher wage applies to all workers, not just the new one. This makes the marginal factor cost (MFC) curve lie above the labor supply curve.'),
        q(53, 'According to the least-cost rule, a firm employing multiple inputs minimizes its cost of production when:', ['It uses only the cheapest input available', 'The marginal product per dollar spent is equal across all inputs (MPL/PL = MPK/PK)', 'It uses equal quantities of all inputs', 'Marginal cost equals average total cost'], 1, 'The least-cost rule states that cost is minimized when the last dollar spent on each input yields the same additional output: MPL/PL = MPK/PK. If the ratios are unequal, the firm can reduce costs by reallocating spending from the input with the lower ratio to the one with the higher ratio.'),
        q(54, 'The wage differential between a surgeon and a janitor is primarily explained by:', ['Government regulation of wages', 'Differences in marginal revenue product due to differences in human capital, skill requirements, and the value of output produced', 'Random variation in the labor market', 'Differences in the number of hours worked'], 1, 'Wage differentials reflect differences in MRP. Surgeons have high MRP due to extensive human capital (years of education and training), scarce specialized skills, and high value of their output. Janitors require less specialized skills, have a larger labor supply, and produce lower-valued output, resulting in lower MRP and wages.'),
        q(55, 'If a labor union successfully negotiates a wage above the competitive equilibrium in a particular market, the most likely effect is:', ['Employment in that market increases.', 'Employment decreases because the higher wage causes quantity demanded of labor to fall below the quantity supplied, creating a surplus of workers.', 'There is no effect on employment.', 'The demand for labor shifts rightward.'], 1, 'A union-negotiated wage above equilibrium functions like a price floor in the labor market. At the higher wage, firms demand fewer workers (moving up along the demand curve) while more workers want to work (moving up along the supply curve). The result is a surplus of labor—unemployment among union members or the industry.'),
      ],
      hard: [
        q(56, 'A monopsony employer hires workers where MRP = MFC rather than MRP = W. Compared to a competitive labor market, the monopsony results in:', ['Higher wages and more employment', 'Lower wages and less employment, creating deadweight loss because the wage is below MRP for the last worker hired', 'The same wages and employment as perfect competition', 'Higher wages and less employment'], 1, 'A monopsony hires where MRP = MFC (not MRP = W). Since MFC > W (the labor supply curve), the monopsony hires fewer workers than a competitive market and pays the wage on the supply curve for that quantity—which is below both MRP and MFC. This creates deadweight loss and transfers surplus from workers to the firm.'),
        q(57, 'A firm uses labor and capital. Currently, MPL/PL = 8 and MPK/PK = 5. To minimize costs while maintaining output, the firm should:', ['Hire more capital and less labor', 'Hire more labor and less capital, because labor currently provides more output per dollar spent', 'Maintain current input levels', 'Hire more of both inputs'], 1, 'Since MPL/PL (8) > MPK/PK (5), the last dollar spent on labor produces more additional output than the last dollar spent on capital. The firm should substitute labor for capital: hiring more labor (reducing MPL via diminishing returns) and using less capital (increasing MPK). This continues until the ratios are equalized.'),
        q(58, 'An increase in immigration increases the supply of unskilled labor. Using the factor market model, predict the effects on wages of unskilled workers and the rental rate of capital.', ['Both wages and rental rates increase.', 'Unskilled wages decrease (increased labor supply reduces the equilibrium wage), while the rental rate of capital may increase (more workers make each unit of capital more productive, increasing demand for capital).', 'Both wages and rental rates decrease.', 'Unskilled wages increase and rental rates decrease.'], 1, 'Increased immigration shifts the supply of unskilled labor rightward, lowering the equilibrium unskilled wage. With more workers available, each unit of capital has more workers to complement it, potentially increasing capital\'s marginal product and thus the demand for and rental rate of capital. Labor and capital are often complementary inputs.'),
        q(59, 'Economic rent in factor markets is best described as:', ['The monthly payment for renting equipment or property.', 'The payment to a factor of production above the minimum amount necessary to keep it in its current use—the area above the factor supply curve and below the equilibrium price.', 'The total payment made to all factors of production.', 'The opportunity cost of using a resource.'], 1, 'Economic rent is the payment above a factor\'s opportunity cost—what it could earn in its next best use. Graphically, it is the area above the supply curve and below the equilibrium factor price. Factors with perfectly inelastic supply (like unique land or talent) earn entirely economic rent.'),
        q(60, 'A bilateral monopoly exists when a monopsony employer faces a monopoly union. The economic prediction for wage and employment outcomes in this situation is:', ['The wage will definitely be lower than the competitive wage.', 'The wage outcome is indeterminate—it depends on the relative bargaining power of the union and the firm—but the wage will fall between the monopsony wage and the union\'s desired wage.', 'The wage will be exactly at the competitive level.', 'Both sides will agree to maximize total employment.'], 1, 'In a bilateral monopoly, the monopsony wants to pay a low wage (where MRP = MFC) and the union wants a high wage (above competitive equilibrium). Theory predicts the outcome falls somewhere between these extremes, but the exact wage depends on the relative bargaining power of each side. Employment may actually be closer to the competitive level than under pure monopsony.'),
      ],
    },
    {
      unitNumber: 5,
      title: 'Market Failure and the Role of Government',
      easy: [
        q(61, 'A negative externality occurs when:', ['A firm\'s production costs increase due to government regulation.', 'The production or consumption of a good imposes costs on third parties who are not involved in the transaction.', 'A consumer does not receive the full benefit of a purchase.', 'The market price is too low to cover production costs.'], 1, 'A negative externality exists when the production or consumption of a good creates costs for people not directly involved in the market transaction. Pollution is the classic example: a factory\'s emissions impose health and environmental costs on the surrounding community.'),
        q(62, 'Public goods are characterized by which two properties?', ['Rivalry and excludability', 'Non-rivalry and non-excludability', 'Scarcity and high cost', 'Government ownership and free distribution'], 1, 'Public goods have two defining characteristics: non-rivalry (one person\'s use doesn\'t diminish another\'s ability to use it) and non-excludability (it is impossible or impractical to prevent anyone from using the good). Examples include national defense, street lights, and clean air.'),
        q(63, 'The free rider problem associated with public goods occurs because:', ['People ride public transportation without paying.', 'People can benefit from a public good without paying for it, reducing the incentive for private markets to provide the good.', 'The government charges too much for public services.', 'Competition eliminates profits for public good providers.'], 1, 'Since public goods are non-excludable, people can enjoy their benefits without paying. This reduces the incentive for individuals to voluntarily contribute, and private markets will underproduce or not produce public goods at all, providing justification for government provision.'),
        q(64, 'A Pigouvian tax is designed to:', ['Generate maximum government revenue', 'Correct a negative externality by taxing the activity that creates it, making the private cost equal the social cost', 'Protect domestic industries from foreign competition', 'Reduce income inequality'], 1, 'A Pigouvian tax is set equal to the marginal external cost of an activity. By adding this tax to private costs, it makes producers and consumers face the full social cost of their decisions, leading to the socially optimal level of production and internalizing the externality.'),
        q(65, 'Income inequality in the United States is measured by the:', ['Consumer Price Index', 'Gini coefficient and the Lorenz curve', 'GDP deflator', 'Unemployment rate'], 1, 'The Gini coefficient (ranging from 0 = perfect equality to 1 = perfect inequality) and the Lorenz curve (which plots cumulative income share against cumulative population share) are the primary tools for measuring income inequality within a country.'),
      ],
      medium: [
        q(66, 'When a negative externality exists in a market, the unregulated market outcome produces:', ['The socially optimal quantity', 'More than the socially optimal quantity because the market price doesn\'t reflect the full social cost, leading to overproduction', 'Less than the socially optimal quantity', 'Exactly the right amount if consumers are rational'], 1, 'With negative externalities, the social cost of production exceeds the private cost. The market price (based on private cost) is too low, leading to overconsumption and overproduction relative to the socially optimal quantity. The marginal social cost curve lies above the marginal private cost curve.'),
        q(67, 'The Coase theorem suggests that externality problems can be resolved without government intervention when:', ['Externalities are very large', 'Property rights are well-defined and transaction costs are low, allowing affected parties to negotiate an efficient outcome regardless of the initial assignment of rights', 'There are many parties involved', 'The externality affects only one person'], 1, 'The Coase theorem states that if property rights are clearly defined and transaction costs are low, private parties can negotiate to reach the efficient outcome regardless of who holds the property rights. However, in practice, high transaction costs and many affected parties often prevent Coasean bargaining.'),
        q(68, 'A common resource (common pool resource) differs from a public good because:', ['Common resources are both excludable and rival.', 'Common resources are rival but non-excludable, leading to the tragedy of the commons—overuse and depletion because users don\'t bear the full cost of their consumption.', 'Common resources are non-rival and excludable.', 'Common resources and public goods are identical concepts.'], 1, 'Common resources are rival (one person\'s use reduces availability for others) but non-excludable (difficult to prevent access). This combination leads to overexploitation—the tragedy of the commons—because each user bears only a fraction of the cost of their use while enjoying the full benefit. Examples include ocean fisheries and public grazing land.'),
        q(69, 'Antitrust legislation serves which primary purpose?', ['Protecting individual firms from competition', 'Promoting competition and preventing monopolistic practices that harm consumers by restricting output and raising prices', 'Guaranteeing profits for all firms in an industry', 'Setting prices for all goods and services in the economy'], 1, 'Antitrust laws (Sherman Act, Clayton Act, FTC Act) aim to promote competition by preventing mergers that substantially reduce competition, prohibiting price-fixing and market allocation agreements among competitors, and outlawing monopolistic practices that harm consumer welfare through higher prices, reduced output, or diminished innovation.'),
        q(70, 'A subsidy provided to producers of a good with a positive externality is designed to:', ['Increase the cost of production', 'Increase production toward the socially optimal level by lowering private costs so that marginal private cost approaches marginal social cost', 'Decrease the quality of the good', 'Eliminate all private production of the good'], 1, 'When a positive externality exists, the social benefit exceeds the private benefit, leading to underproduction. A subsidy reduces the producer\'s cost, shifting the supply curve rightward and increasing output toward the socially optimal quantity where marginal social benefit equals marginal social cost.'),
      ],
      hard: [
        q(71, 'A factory emits pollution that harms a nearby fishery. Using the Coase theorem framework, if property rights are assigned to the fishery (right to clean water), the efficient outcome is achieved when:', ['The factory shuts down completely.', 'The factory pays the fishery for the right to pollute up to the level where the factory\'s marginal benefit from pollution equals the fishery\'s marginal damage—reaching the socially efficient level of pollution.', 'The fishery relocates to avoid the pollution.', 'The factory pollutes without restriction because it had no prior obligation.'], 1, 'With property rights assigned to the fishery, the factory must compensate the fishery for pollution damage. The factory will pay for the right to pollute only when its marginal benefit from production exceeds the fishery\'s marginal damage. Negotiation leads to the efficient level of pollution where the marginal benefit of pollution equals its marginal cost (damage)—the same efficient outcome regardless of initial rights assignment.'),
        q(72, 'A government considers two approaches to reducing carbon emissions: a carbon tax and a cap-and-trade system. Which analysis of their relative advantages is most accurate?', ['They are economically identical in all respects.', 'A carbon tax provides price certainty (firms know the cost per ton of emissions) but quantity uncertainty; cap-and-trade provides quantity certainty (total emissions are capped) but price uncertainty, as the permit price fluctuates with market conditions.', 'Cap-and-trade always achieves lower emissions than a carbon tax.', 'A carbon tax is always preferred because it generates government revenue.'], 1, 'The key difference is which variable is fixed and which adjusts. A carbon tax fixes the price of emissions (tax rate), and the quantity of emissions adjusts based on firms\' responses. Cap-and-trade fixes the total quantity of emissions (the cap), and the price of emission permits adjusts through market trading. Each approach has advantages depending on whether policymakers prioritize cost predictability or emissions certainty.'),
        q(73, 'The concept of "moral hazard" in economics describes situations where:', ['Firms engage in unethical business practices.', 'One party changes their behavior after entering an agreement because they are insulated from the full consequences of their actions, increasing risk for the other party.', 'Consumers always act in their own self-interest.', 'Markets always reach efficient outcomes.'], 1, 'Moral hazard occurs when insurance or other protection causes the insured party to take more risks than they would otherwise. For example, a person with comprehensive car insurance may drive less carefully because they don\'t bear the full cost of accidents. The party bearing the risk (insurer) cannot fully observe or control the other party\'s behavior.'),
        q(74, 'The Lorenz curve for Country X shows that the bottom 40% of the population earns 10% of total income, while the bottom 40% in Country Y earns 25% of total income. Which country has greater income inequality and how does this relate to the Gini coefficient?', ['Country Y has greater inequality with a higher Gini coefficient.', 'Country X has greater inequality; its Lorenz curve bows farther from the line of equality, resulting in a higher Gini coefficient (larger area between the Lorenz curve and the line of equality).', 'Both countries have equal inequality.', 'Income inequality cannot be compared between countries using the Lorenz curve.'], 1, 'Country X\'s bottom 40% earning only 10% of income indicates much greater inequality than Country Y\'s bottom 40% earning 25%. Country X\'s Lorenz curve bows further from the 45-degree line of perfect equality. The Gini coefficient (the ratio of the area between the Lorenz curve and the equality line to the total area under the equality line) is higher for Country X, indicating greater inequality.'),
        q(75, 'Asymmetric information in a used car market leads to "adverse selection." Which mechanism explains this market failure?', ['Sellers have no information about their cars\' quality.', 'Sellers know the quality of their cars but buyers cannot distinguish good cars from lemons; buyers offer low prices reflecting average quality, driving good-car owners out of the market and leaving disproportionately many lemons—reducing market quality and volume.', 'Buyers always know more about car quality than sellers.', 'Government regulation prevents the sale of high-quality used cars.'], 1, 'Adverse selection (Akerlof\'s "Market for Lemons") occurs because of asymmetric information: sellers know quality, buyers don\'t. Buyers rationally offer prices reflecting average quality. Owners of good cars find these prices too low and withdraw from the market. This worsens the average quality of remaining cars, further reducing prices, in a self-reinforcing cycle that can cause market collapse—a clear market failure.'),
      ],
    },
  ],
}
